V="/c/Users/coneil/AppData/Local/Temp/claude/87995a179e8ca25a/62d1c137-a316-4c55-b30a-3f6dac53053e/scratchpad/research/ct-physics/verify"; cat > "$V/scripts/calc.js" <<'EOF'
// Independent recomputation for the ct-physics batch (fact-check pass).
const fs=require('fs'),path=require('path');
const dl=process.argv[2];
const mats=[
 {key:'air',name:'Air (dry, near sea level)',rho:1.205e-3,file:'air'},
 {key:'lung',name:'Inflated lung',rho:0.26,file:'lung'},
 {key:'adipose',name:'Adipose tissue (fat)',rho:0.95,file:'adipose'},
 {key:'water',name:'Water (liquid)',rho:1.0,file:'water'},
 {key:'tissue',name:'Soft tissue (ICRU-44)',rho:1.06,file:'tissue'},
 {key:'muscle',name:'Skeletal muscle (ICRU-44)',rho:1.05,file:'muscle'},
 {key:'bone',name:'Cortical bone (ICRU-44)',rho:1.92,file:'bone'}];
function nistRow(file,e){ // read ASCII block of the NIST page
  const h=fs.readFileSync(path.join(dl,'nist_'+file+'.html'),'utf8');
  const re=new RegExp('^\\s*'+e.replace('+','\\+')+'\\s+(\\S+)\\s+(\\S+)\\s*$','m');
  const m=h.match(re); if(!m) throw new Error('no row '+file+' '+e); return parseFloat(m[1]);
}
function xcom(file){
  const h=fs.readFileSync(path.join(dl,'myxcom_'+file+'.html'),'utf8').replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ');
  const out={};
  for(const line of h.split('\n')){const m=line.trim().match(/^(\d\.\d{3}E[-+]\d\d)\s+(\S+)\s+(\S+)\s+(\S+)\s+(\S+)\s+(\S+)\s+(\S+)\s+(\S+)$/);
    if(m){out[parseFloat(m[1]).toFixed(4)]={coh:+m[2],inc:+m[3],pe:+m[4],tot:+m[7]};}}
  return out;
}
const ll=(e,e1,m1,e2,m2)=>Math.exp(Math.log(m1)+(Math.log(m2)-Math.log(m1))*(Math.log(e/e1)/Math.log(e2/e1)));
const sig=(x,n)=>Number(x.toPrecision(n));
const res={};
for(const m of mats){
  const a60=nistRow(m.file,'6.00000E-02'),a80=nistRow(m.file,'8.00000E-02'),a500=nistRow(m.file,'5.00000E-01'),a600=nistRow(m.file,'6.00000E-01');
  const m70=ll(70,60,a60,80,a80), m511=ll(511,500,a500,600,a600);
  const x=xcom(m.file);
  res[m.key]={name:m.name,rho:m.rho,a60,a80,a500,a600,ma70:m70,ma511:m511,mu70:m70*m.rho,mu511:m511*m.rho,mu60:a60*m.rho,mu80:a80*m.rho,
    x:x, xmu70:x['0.0700'].tot*m.rho, xmu511:x['0.5110'].tot*m.rho};
}
const w=res.water,a=res.air;
console.log('== attenuation ==');
for(const k in res){const r=res[k];
  const hu=(mu,muw,mua)=>1000*(mu-muw)/(muw-mua), hu1=(mu,muw)=>1000*(mu-muw)/muw;
  r.hu70=hu(r.mu70,w.mu70,a.mu70); r.hu60=hu(r.mu60,w.mu60,a.mu60); r.hu80=hu(r.mu80,w.mu80,a.mu80);
  r.hu70_iaea=hu1(r.mu70,w.mu70); r.xhu70=hu(r.xmu70,w.xmu70,a.xmu70);
  console.log(k.padEnd(8),'rho',r.rho,'| NIST',r.a60,r.a80,r.a500,r.a600,'| ma70',sig(r.ma70,5),'ma511',sig(r.ma511,5),'| mu70',sig(r.mu70,5),'mu511',sig(r.mu511,5),
   '| XCOM ma70',r.x['0.0700'].tot,'ma511',r.x['0.5110'].tot,'xmu70',sig(r.xmu70,5),'xmu511',sig(r.xmu511,5),
   '| diff70 %',sig(100*(r.ma70/r.x['0.0700'].tot-1),3),'diff511 %',sig(100*(r.ma511/r.x['0.5110'].tot-1),3));
  console.log('   HVL70',sig(Math.LN2/r.mu70,4),'HVL511',sig(Math.LN2/r.mu511,4),'xHVL70',sig(Math.LN2/r.xmu70,4),'| HU60',r.hu60.toFixed(1),'HU70',r.hu70.toFixed(1),'HU80',r.hu80.toFixed(1),'HU70(IAEA form)',r.hu70_iaea.toFixed(2),'xHU70',r.xhu70.toFixed(1));
  // XCOM check that it reproduces table at 60,80,500,600
  console.log('   xcom@60',r.x['0.0600'].tot,'@80',r.x['0.0800'].tot,'@500',r.x['0.5000'].tot,'@600',r.x['0.6000'].tot);
}
console.log('\n== transmission 70 keV (loglog mu | xcom mu | 511 loglog) ==');
for(const k in res){const r=res[k];const t=[1,5,10,20];
  console.log(k.padEnd(8),'mu',sig(r.mu70,4),t.map(d=>(100*Math.exp(-r.mu70*d)).toPrecision(5)).join(' / '),'| x',t.map(d=>(100*Math.exp(-r.xmu70*d)).toPrecision(5)).join(' / '),'| 511',t.map(d=>(100*Math.exp(-r.mu511*d)).toPrecision(5)).join(' / '));
  // with mu rounded to 4 sig first (as a reader would compute from the table)
  const mr=sig(r.mu70,4); console.log('         from rounded mu',mr,t.map(d=>(100*Math.exp(-mr*d)).toPrecision(5)).join(' / '));
}
console.log('\n== interactions ==');
for(const k of ['water','tissue','adipose','muscle','lung','bone','air']){const r=res[k];
  for(const e of ['0.0500','0.0550','0.0600','0.0700','0.0800','0.5110']){const p=r.x[e];
   console.log(k.padEnd(8),e,'coh',p.coh,'inc',p.inc,'pe',p.pe,'tot',p.tot,'| pe%',(100*p.pe/p.tot).toFixed(2),'compton%',(100*p.inc/p.tot).toFixed(2),'rayleigh%',(100*p.coh/p.tot).toFixed(2));}
}
const b=res.bone;
console.log('\nratios: bone/water mu70 loglog',b.mu70/w.mu70,'xcom',b.xmu70/w.xmu70,'511',b.mu511/w.mu511,'x511',b.xmu511/w.xmu511);
console.log('mu511/mu70 water xcom',w.xmu511/w.xmu70,'loglog',w.mu511/w.mu70,'bone xcom',b.xmu511/b.xmu70,'loglog',b.mu511/b.mu70);
console.log('pe per g bone/water @70',b.x['0.0700'].pe/w.x['0.0700'].pe,'per cm',b.x['0.0700'].pe*1.92/w.x['0.0700'].pe);
for(const k of ['muscle','tissue','adipose']) console.log(k,'vs water mu70 %',100*(res[k].mu70/w.mu70-1),'xcom',100*(res[k].xmu70/w.xmu70-1));
console.log('water/air mu70',w.mu70/a.mu70,'xcom',w.xmu70/a.xmu70);
console.log('\n== pair survival 511 (water) ==');
for(const D of [10,20,30,40]){const s=Math.exp(-w.mu511*D);console.log(D,'cm',(100*s).toPrecision(4),'% factor',(1/s).toPrecision(4));}
console.log('\n== compton ==');
const comp=(E,deg)=>E/(1+(E/510.999)*(1-Math.cos(deg*Math.PI/180)));
for(const E of [70,511]) for(const d of [90,180]) console.log(E,d,comp(E,d).toFixed(2));
console.log('\n== misc ==');
console.log('carney lung -742:',9.6e-5*(1000-742), 'lung mu511',res.lung.mu511);
console.log('turns/s:',[0.5,0.33,0.25,0.23,0.24,0.28,0.3,0.35].map(t=>t+':'+(1/t).toFixed(2)).join(' '));
console.log('table feed 64x0.6 pitch1 0.5s:',64*0.6/0.5,'mm/s -> 100 cm in',1000/(64*0.6/0.5),'s');
console.log('1 HU =',100/1000,'% of mu_water');
console.log('1cm removal % water70',100*(1-Math.exp(-w.mu70)),'x',100*(1-Math.exp(-w.xmu70)),'water511',100*(1-Math.exp(-w.mu511)),'bone70',100*(1-Math.exp(-b.mu70)),'x',100*(1-Math.exp(-b.xmu70)),'fat',100*(1-Math.exp(-res.adipose.mu70)),'lung',100*(1-Math.exp(-res.lung.mu70)),'muscle',100*(1-Math.exp(-res.muscle.mu70)),'air',100*(1-Math.exp(-a.mu70)));
fs.writeFileSync(path.join(path.dirname(dl),'scripts','calc_out.json'),JSON.stringify(res,null,1));
EOF
node "$V/scripts/calc.js" "$V/dl"

